input.command:
for svc in ams wms pms input power sensor; do
  case $svc in
    ams)   DIR="$HOME/aosp/base/services/core/java/com/android/server/am/docs/exploration/" ;;
    wms)   DIR="$HOME/aosp/base/services/core/java/com/android/server/wm/docs/exploration/" ;;
    pms)   DIR="$HOME/aosp/base/services/core/java/com/android/server/pm/docs/exploration/" ;;
    input) DIR="$HOME/aosp/base/services/core/java/com/android/server/input/docs/exploration/" ;;
    power) DIR="$HOME/aosp/base/services/core/java/com/android/server/power/docs/exploration/" ;;
    sensor) DIR="$HOME/aosp/base/core/java/android/hardware/docs/exploration/" ;;
  esac
  echo "=== $svc ==="
  ls "$DIR" 2>/dev/null | sort
done
